window.GRILE_QUESTION_SHARDS=window.GRILE_QUESTION_SHARDS||{};window.GRILE_QUESTION_SHARDS["shard-121"]=[{"id":"set2-UQg-1gGG","fingerprint":"27180ee0b9f0058e","chapterId":"set-2","subchapterId":"set2-5.06","type":"CS","text":"Conform periodicizării dezvoltării copilului, care este intervalul de vârstă corespunzător perioadei școlare?","options":[{"id":"A","text":"2-6 ani"},{"id":"B","text":"0-2 ani"},{"id":"C","text":"6-11 ani"},{"id":"D","text":"12-15 ani"},{"id":"E","text":"6-12 ani"}],"correct":["C"],"pages":[443],"source":"set-2"},{"id":"set2-27Qdf4QJ","fingerprint":"4ff25333f13bbcd5","chapterId":"set-2","subchapterId":"set2-5.06","type":"CM","text":"Care dintre următoarele afirmații referitoare la managementul copilului în perioada micii copilării (0-2 ani) în cabinetul stomatologic sunt adevărate?","options":[{"id":"A","text":"Se recomandă prezența fraților în cabinet, deoarece plânsul pacientului nu îi afectează."},{"id":"B","text":"Plânsul copilului la această vârstă este considerat mai mult un semn de disconfort decât de frică reală sau durere."},{"id":"C","text":"Ședința de tratament trebuie să fie scurtă, deoarece puterea de concentrare variază între 1 și 5 minute."},{"id":"D","text":"Este utilă negocierea cu copilul, deoarece acesta poate înțelege beneficiile tratamentului dacă i se explică."},{"id":"E","text":"Copilul nu trebuie separat de mamă, aceasta având rolul de a-l ține în brațe pentru a facilita examenul clinic."}],"correct":["B","C","E"],"pages":[443],"source":"set-2"},{"id":"set2-urMR97M6","fingerprint":"807163c71dcf86e7","chapterId":"set-2","subchapterId":"set2-5.06","type":"CS","text":"Ce atitudine specifică trebuie să adopte medicul în timpul examinării unui copil din grupa de vârstă 0-2 ani?","options":[{"id":"A","text":"Să programeze ședința la finalul zilei, când copilul este mai obosit."},{"id":"B","text":"Să încerce să raționeze cu copilul pentru a obține cooperarea acestuia."},{"id":"C","text":"Să ignore plânsul copilului, deoarece este întotdeauna un semn de sfidare."},{"id":"D","text":"Să se concentreze exclusiv asupra micului pacient, fără a fi deranjat de părinți sau personal."},{"id":"E","text":"Trebuie evitate întrebările care pot primi un răspuns negativ, precum „Vrei să te așezi pe fotoliu?”."}],"correct":["D"],"pages":[443],"source":"set-2"},{"id":"set2-cCRRUHJ8","fingerprint":"57a85eb0321bb4a1","chapterId":"set-2","subchapterId":"set2-5.06","type":"CM","text":"Care sunt recomandările specifice pentru abordarea unui copil preșcolar cu vârsta între 2 și 4 ani în cabinetul stomatologic?","options":[{"id":"A","text":"Este de preferat ca ședința să fie programată la finalul zilei, când copilul este mai calm."},{"id":"B","text":"Capacitatea de concentrare a atenției copilului este de aproximativ 15 minute, permițând ședințe mai lungi."},{"id":"C","text":"Stabilirea unor „ritualuri” în derularea ședințelor are rolul de a liniști copilul."},{"id":"D","text":"Părinții trebuie să rămână în cabinet pentru a-l liniști, deoarece copilul este foarte dependent de ei."},{"id":"E","text":"Medicul poate număra cu voce tare timpul rămas dintr-o procedură pentru a compensa lipsa noțiunii timpului la copil."}],"correct":["C","E"],"pages":[443],"source":"set-2"},{"id":"set2-lfl77vYx","fingerprint":"8813b8a80d84a167","chapterId":"set-2","subchapterId":"set2-5.06","type":"CM","text":"Care este o diferență cheie în managementul pacientului pediatric din mica copilărie (0-2 ani) față de cel din perioada preșcolară (2-4 ani)?","options":[{"id":"A","text":"Permiterea copilului de 0-2 ani să ajute, de exemplu prin a ține un rulou de vată."},{"id":"B","text":"Modularea vocii este eficientă pentru a capta atenția la 2-4 ani, dar ineficientă la 0-2 ani."},{"id":"C","text":"Prezența părintelui în cabinet este esențială la 0-2 ani, în timp ce la 2-4 ani se recomandă ca părintele să aștepte afară."},{"id":"D","text":"Ședințele sunt scurte la 0-2 ani (1-5 min), dar pot fi prelungite la 2-4 ani datorită cooperării mai bune."},{"id":"E","text":"Negocierea este posibilă cu copilul de 2-4 ani, spre deosebire de cel de 0-2 ani."}],"correct":["C","D"],"pages":[443],"source":"set-2"},{"id":"set2-PnIJN0xA","fingerprint":"074b487d7b3cf40e","chapterId":"set-2","subchapterId":"set2-5.06","type":"CM","text":"Care sunt abordările corecte în comunicarea cu un copil preșcolar, cu vârsta între 4 și 6 ani, în cabinetul stomatologic?","options":[{"id":"A","text":"Implicarea activă a copilului în tratament, permițându-i să țină oglinda sau un rulou de vată."},{"id":"B","text":"Utilizarea poveștilor și a personajelor pe care copilul le îndrăgește pentru a explica procedurile."},{"id":"C","text":"Părintele trebuie să asiste la fiecare ședință de tratament pentru a oferi suport copilului."},{"id":"D","text":"Este indicat să se lucreze cu pauze frecvente pentru a nu suprasolicita atenția copilului."},{"id":"E","text":"Laudarea îmbrăcămintei copilului pentru a capta atenția și a stabili o relație pozitivă."}],"correct":["A","B","E"],"pages":[444],"source":"set-2"},{"id":"set2-QlQIImvd","fingerprint":"37fa3f9f2721a7af","chapterId":"set-2","subchapterId":"set2-5.06","type":"CS","text":"Ce atitudine trebuie să adopte medicul stomatolog atunci când un pacient școlar (6-11 ani) cu temperament coleric refuză tratamentul?","options":[{"id":"A","text":"Să își păstreze calmul și să facă apel la amorul propriu, mândria sau curajul copilului."},{"id":"B","text":"Să solicite imediat intervenția părintelui pentru a-l convinge pe copil să coopereze."},{"id":"C","text":"Să întrerupă ședința și să o reprogrameze, considerând că pacientul nu este pregătit."},{"id":"D","text":"Să încerce să convingă copilul prin argumente raționale despre importanța tratamentului."},{"id":"E","text":"Să îi vorbească despre campioni sportivi pentru a-i distrage atenția de la refuz."}],"correct":["A"],"pages":[444],"source":"set-2"},{"id":"set2-fc_fy2ge","fingerprint":"fdbe9643d7a203c5","chapterId":"set-2","subchapterId":"set2-5.06","type":"CS","text":"Care este cea mai eficientă strategie de motivare a unui adolescent (12-15 ani) pentru menținerea igienei orale?","options":[{"id":"A","text":"Abordarea subiectului igienei orale doar în prima ședință a unui tratament complex."},{"id":"B","text":"Furnizarea de explicații logice, bazate pe capacitatea de raționament și deducere a adolescentului."},{"id":"C","text":"Criticarea directă a igienei precare pentru a-l conștientiza de gravitate."},{"id":"D","text":"Apelarea la povești cu super-eroi care au o igienă orală perfectă."},{"id":"E","text":"Interzicerea strictă a consumului de zahăr pentru a preveni apariția cariilor."}],"correct":["B"],"pages":[444],"source":"set-2"},{"id":"set2-oBTCXmA2","fingerprint":"dc6fbaca64d808ed","chapterId":"set-2","subchapterId":"set2-5.06","type":"CS","text":"Conform definițiilor clinice, care este diferența fundamentală dintre frică și anxietate în contextul stomatologic?","options":[{"id":"A","text":"Frica apare exclusiv la prima vizită, iar anxietatea se manifestă la ședințele ulterioare."},{"id":"B","text":"Frica se bazează pe percepția unei amenințări reale, iar anxietatea este reacția de frică la o situație anticipată și nerealistă."},{"id":"C","text":"Nu există nicio diferență, termenii de „frică dentară” și „anxietate dentară” fiind sinonimi perfecți."},{"id":"D","text":"Anxietatea este o emoție naturală, în timp ce frica este o afecțiune dezvoltată de copiii care nu s-au putut adapta."},{"id":"E","text":"Frica este o reacție la o amenințare anticipată, dar nerealistă, în timp ce anxietatea se bazează pe o amenințare reală."}],"correct":["B"],"pages":[444],"source":"set-2"},{"id":"set2-VL9Kp1k0","fingerprint":"7fe3f8972f70c536","chapterId":"set-2","subchapterId":"set2-5.06","type":"CM","text":"Care afirmații descriu corect evoluția fricii și a anxietății dentare în funcție de vârsta copilului?","options":[{"id":"A","text":"Frica și problemele de comportament ating un apogeu la vârste mici, după care scad drastic."},{"id":"B","text":"Anxietatea dentară începe în perioada preșcolară și înregistrează o creștere moderată ulterior."},{"id":"C","text":"Frica dispare complet în perioada școlară, în timp ce anxietatea rămâne constantă pe tot parcursul copilăriei."},{"id":"D","text":"Anxietatea dentară debutează în perioada școlară și scade treptat spre adolescență."},{"id":"E","text":"Atât frica, cât și anxietatea dentară, urmează un model evolutiv identic, cu un maxim în adolescență."}],"correct":["A","B"],"pages":[444],"source":"set-2"},{"id":"set2-r8fT1Er2","fingerprint":"c8e3132f8b79b2bd","chapterId":"set-2","subchapterId":"set2-5.06","type":"CM","text":"Care sunt caracteristicile definitorii ale fricii dentare?","options":[{"id":"A","text":"Este o reacție emoțională normală la stimulii amenințători dintr-o situație clinică."},{"id":"B","text":"Se referă la un pericol iminent, vag și nedeterminat."},{"id":"C","text":"Se manifestă întotdeauna prin atitudini dramatice sau isterice."},{"id":"D","text":"Reprezintă reacția la un stimul extern specific și amenințător."},{"id":"E","text":"Poate include o stare de agitație motorie."}],"correct":["A","D","E"],"pages":[445],"source":"set-2"},{"id":"set2-A-oT-Fil","fingerprint":"f66ee4cfd6800dc1","chapterId":"set-2","subchapterId":"set2-5.06","type":"CS","text":"Ce element diferențiază fundamental anxietatea dentară de frica dentară?","options":[{"id":"A","text":"Frica este o reacție emoțională, în timp ce anxietatea este o problemă de comportament."},{"id":"B","text":"Frica duce la amânarea vizitelor la medic, în timp ce anxietatea nu."},{"id":"C","text":"Anxietatea se referă la un pericol vag și nedeterminat, în timp ce frica se leagă de un obiect specific."},{"id":"D","text":"Anxietatea reprezintă o reacție la un stimul extern amenințător."},{"id":"E","text":"Anxietatea este întotdeauna mai severă decât frica."}],"correct":["C"],"pages":[445],"source":"set-2"},{"id":"set2-oaW6nzln","fingerprint":"2d8d2e059dc95989","chapterId":"set-2","subchapterId":"set2-5.06","type":"CM","text":"Care dintre următoarele afirmații descriu corect odontofobia?","options":[{"id":"A","text":"Este considerată un tip sever de anxietate dentară."},{"id":"B","text":"Se manifestă doar printr-o ușoară neliniște."},{"id":"C","text":"Se caracterizează printr-o frică marcată și persistentă față de situații sau obiecte specifice."},{"id":"D","text":"Poate interfera semnificativ cu rutina zilnică și viața socială a pacientului."},{"id":"E","text":"Este o reacție emoțională normală în contextul unui tratament stomatologic."}],"correct":["A","C","D"],"pages":[445],"source":"set-2"},{"id":"set2-t-6BVyvw","fingerprint":"9fd084f1615b1a36","chapterId":"set-2","subchapterId":"set2-5.06","type":"CS","text":"Cum este descrisă relația dintre problemele de comportament observate de medic și stările interioare ale copilului?","options":[{"id":"A","text":"Problemele de comportament reprezintă ceea ce pacientul simte, iar frica este ceea ce medicul observă."},{"id":"B","text":"Un copil cu probleme de comportament manifestă întotdeauna frică sau anxietate dentară."},{"id":"C","text":"Toți copiii care simt frică și anxietate dentară manifestă probleme de comportament."},{"id":"D","text":"Cele două noțiuni, comportamentul observat și starea simțită, nu se corelează întotdeauna."},{"id":"E","text":"Distingerea corectă a fricii dentare de problemele de comportament este întotdeauna simplă într-o situație clinică."}],"correct":["D"],"pages":[445],"source":"set-2"},{"id":"set2-RuQ39d85","fingerprint":"110cbe119fde2c41","chapterId":"set-2","subchapterId":"set2-5.06","type":"CS","text":"Ce risc major apare în cazul în care un medic stomatolog consideră doar comportamentul cooperant al unui copil pasiv și tăcut ca semn de confort?","options":[{"id":"A","text":"Părinții vor considera că medicul nu este suficient de atent."},{"id":"B","text":"Se confirmă faptul că un copil pasiv nu experimentează niciodată frică."},{"id":"C","text":"Acest comportament indică întotdeauna o înțelegere limitată a procedurilor."},{"id":"D","text":"Copilul va deveni zgomotos și se va opune fizic tratamentului."},{"id":"E","text":"Anxietatea copilului poate fi trecută cu vederea, crescând riscul de a-i provoca suferință."}],"correct":["E"],"pages":[445],"source":"set-2"},{"id":"set2---u6vP7L","fingerprint":"441ebbbee913de35","chapterId":"set-2","subchapterId":"set2-5.06","type":"CS","text":"Conform tipurilor de comportament prezentate, cum este descris un copil cu timiditate?","options":[{"id":"A","text":"Prezintă iritabilitate și devine ușor agresiv când este frustrat."},{"id":"B","text":"Are tendința de a fi mai lent și necesită un timp de adaptare în situații noi."},{"id":"C","text":"Se opune fizic tratamentului stomatologic."},{"id":"D","text":"Vorbește în șoaptă mamei și evită contactul vizual cu medicul."},{"id":"E","text":"Este extrovertit în comportamentul său general."}],"correct":["B"],"pages":[445],"source":"set-2"},{"id":"set2-l7dCGCTb","fingerprint":"d7f7704a4905414b","chapterId":"set-2","subchapterId":"set2-5.06","type":"CM","text":"Care dintre următoarele tipuri de comportament sunt asociate cu frica dentară și/sau probleme de comportament?","options":[{"id":"A","text":"Cooperare activă, manifestată prin interes crescut față de procedurile stomatologice."},{"id":"B","text":"Impulsivitate, caracterizată prin nerăbdare și lipsa perseverenței."},{"id":"C","text":"Hiperreactivitate, definită ca tendința de a se grăbi sau de a interveni rapid în discuții."},{"id":"D","text":"Timiditate, caracterizată prin adaptare lentă în situații noi."},{"id":"E","text":"Emoționalitate negativă, manifestată prin iritabilitate și agresivitate la frustrare."}],"correct":["B","C","D","E"],"pages":[446],"source":"set-2"},{"id":"set2--laoAk51","fingerprint":"e3eaed90783b2d59","chapterId":"set-2","subchapterId":"set2-5.06","type":"CS","text":"Care este considerată cea mai elocventă metodă de evaluare a tiparelor comportamentale ale copilului în context stomatologic?","options":[{"id":"A","text":"Observarea directă a răspunsului fiziologic al copilului."},{"id":"B","text":"Chestionarele completate de un părinte."},{"id":"C","text":"Chestionarele completate de copil."},{"id":"D","text":"Utilizarea scalelor de evaluare a comportamentului."},{"id":"E","text":"Discuțiile informale cu educatorul sau învățătorul copilului."}],"correct":["D"],"pages":[446],"source":"set-2"},{"id":"set2-WYHGN9Ht","fingerprint":"ab8b9d5dd64bedc7","chapterId":"set-2","subchapterId":"set2-5.06","type":"CM","text":"Care sunt afirmațiile corecte referitoare la scala de evaluare a comportamentului Frankl?","options":[{"id":"A","text":"Este cea mai utilizată scală de evaluare a comportamentului la copil."},{"id":"B","text":"Principalul său avantaj este că oferă o analiză detaliată și completă a problemelor clinice ale copilului."},{"id":"C","text":"Progresele obținute în comportamentul pacientului sunt notate cu \"+\" pentru evoluție favorabilă sau \"-\" pentru evoluție nefavorabilă."},{"id":"D","text":"Este o scală de la I la V care măsoară exclusiv nivelul de anxietate."},{"id":"E","text":"Un dezavantaj este că nu redă suficiente informații despre cooperarea copilului și problemele clinice."}],"correct":["A","C","E"],"pages":[446],"source":"set-2"},{"id":"set2-AeRxFIT4","fingerprint":"a26524104fa6a8c3","chapterId":"set-2","subchapterId":"set2-5.06","type":"CS","text":"Un copil de vârstă mijlocie plânge intens, manifestă un comportament incontrolabil și refuză orice formă de tratament stomatologic, fiind îngrozit. Conform clasificării lui Frankl, în ce categorie se încadrează acest pacient?","options":[{"id":"A","text":"Tip II = comportament negativ (\"-\")."},{"id":"B","text":"Comportament sfidător."},{"id":"C","text":"Comportament imatur."},{"id":"D","text":"Tip I = comportament total negativ (\"- -\")."},{"id":"E","text":"Comportament timid."}],"correct":["D"],"pages":[446],"source":"set-2"},{"id":"set2-cUUxG1H8","fingerprint":"79adc2cb9b40fe72","chapterId":"set-2","subchapterId":"set2-5.06","type":"CS","text":"Un copil supraprotejat, care intră în contact cu puțini oameni, este retras, îmbufnat și acceptă cu dificultate tratamentul stomatologic, colaborând greu cu echipa medicală. Conform clasificării lui Frankl, ce tip de comportament manifestă acest pacient?","options":[{"id":"A","text":"Tip II = comportament negativ (\"-\")."},{"id":"B","text":"Comportament imatur."},{"id":"C","text":"Comportament sfidător."},{"id":"D","text":"Tip I = comportament total negativ (\"- -\")."},{"id":"E","text":"Comportament necontrolabil."}],"correct":["A"],"pages":[446],"source":"set-2"},{"id":"set2-PbjBkxuf","fingerprint":"2e1ef8286d612bec","chapterId":"set-2","subchapterId":"set2-5.06","type":"CM","text":"Care dintre următoarele manifestări caracterizează comportamentul de Tip I (total negativ, \"- -\") din clasificarea lui Frankl?","options":[{"id":"A","text":"Plâns intens și comportament incontrolabil la un preșcolar mare sau un copil de vârstă mijlocie."},{"id":"B","text":"Rezistența pasivă opusă de un adolescent, asociată unui negativism extrem."},{"id":"C","text":"Refuzul tratamentului de către un copil răsfățat, de vârstă mijlocie, prin rezistență activă/pasivă."},{"id":"D","text":"O atitudine negativă, dar nu pronunțată, a unui copil care acceptă greu tratamentul."},{"id":"E","text":"Comportament timid, vizibil la un copil supraprotejat."}],"correct":["A","B","C"],"pages":[446],"source":"set-2"},{"id":"set2-J4bTtriZ","fingerprint":"e015917d7818bc7a","chapterId":"set-2","subchapterId":"set2-5.06","type":"CM","text":"Conform clasificării lui Frankl, care sunt caracteristicile comportamentului de Tip II (negativ, \"-\")?","options":[{"id":"A","text":"Pacientul are rezerve în acceptarea tratamentului stomatologic."},{"id":"B","text":"Pacientul manifestă o atitudine negativă, dar nu pronunțată, fiind îmbufnat și retras."},{"id":"C","text":"Reprezintă un negativism extrem, în care copilul este îngrozit și refuză complet tratamentul."},{"id":"D","text":"Se poate manifesta ca un comportament timid la un copil supraprotejat, care va colabora greu."},{"id":"E","text":"Este specific copilului care plânge intens și are un comportament incontrolabil."}],"correct":["A","B","D"],"pages":[446],"source":"set-2"},{"id":"set2-r-KyvfA4","fingerprint":"d4a61a62a8aaf266","chapterId":"set-2","subchapterId":"set2-5.06","type":"CS","text":"Care dintre următoarele descrieri caracterizează un pacient copil cu un comportament de Tip III (pozitiv \"+\")?","options":[{"id":"A","text":"Copilul acceptă tratamentul și respectă ședințele, dar poate manifesta o anumită tensiune sau rezerve."},{"id":"B","text":"Copilul urmează instrucțiunile și înțelege pe deplin importanța profilaxiei."},{"id":"C","text":"Copilul este interesat de procedurile stomatologice, se bucură și râde."},{"id":"D","text":"Copilul cooperează doar sub presiunea familiei sau a prietenilor."},{"id":"E","text":"Copilul este timid și plângăreț, refuzând constant orice formă de colaborare."}],"correct":["A"],"pages":[447],"source":"set-2"},{"id":"set2-y3Xav_UA","fingerprint":"ab7cf7955d24feeb","chapterId":"set-2","subchapterId":"set2-5.06","type":"CM","text":"Care dintre următoarele afirmații sunt principii fundamentale ale managementului comportamental în pedodonție?","options":[{"id":"A","text":"Flexibilitatea, adică abilitatea echipei de a-și schimba planul terapeutic în orice moment."},{"id":"B","text":"Organizarea riguroasă a cabinetului, excluzând dialogul cu copilul pentru a preveni anxietatea."},{"id":"C","text":"Toleranța, care presupune gestionarea corectă a comportamentelor nedorite și menținerea calmului."},{"id":"D","text":"Utilizarea prioritară a sedării farmacologice pentru a scurta timpul de tratament."},{"id":"E","text":"Transparența, care implică oferirea de variante precise, de \"alb sau negru\", fără nuanțe intermediare."}],"correct":["A","C","E"],"pages":[447],"source":"set-2"},{"id":"set2-pvDWucJn","fingerprint":"6c9ae42a715cde6f","chapterId":"set-2","subchapterId":"set2-5.06","type":"CS","text":"Ce element distinctiv definește un copil cu comportament de Tip IV (total pozitiv \"++\") față de unul cu Tip III (pozitiv \"+\")?","options":[{"id":"A","text":"Copilul de Tip IV este supraprotejat, în timp ce cel de Tip III este independent."},{"id":"B","text":"Medicii consideră categoria Tip IV greu de tratat, în timp ce Tipul III este considerat ușor de gestionat."},{"id":"C","text":"Doar copilul de Tip III poate fi plângăreț sau irascibil."},{"id":"D","text":"Copilul de Tip IV respectă ședințele, în timp ce cel de Tip III nu o face."},{"id":"E","text":"Copilul de Tip IV are un raport bun cu echipa și înțelege importanța profilaxiei, spre deosebire de cel de Tip III, care doar acceptă tratamentul."}],"correct":["E"],"pages":[447],"source":"set-2"},{"id":"set2-AU-tyyAq","fingerprint":"db9c3cd3a8573c81","chapterId":"set-2","subchapterId":"set2-5.06","type":"CM","text":"Care sunt etapele menționate în secvențializarea managementului comportamental, odată ce pacientul a ajuns în cabinetul stomatologic?","options":[{"id":"A","text":"Obținerea consimțământului asupra diagnosticului și tratamentului propus."},{"id":"B","text":"Inițierea deprinderilor sanogenice în mediul familial."},{"id":"C","text":"Stabilirea planului de tratament fără a consulta copilul pentru a nu-i crea anxietate."},{"id":"D","text":"Controlul permanent al durerii și stress-ului."},{"id":"E","text":"Evaluarea tipologiei comportamentale a copilului."}],"correct":["A","D","E"],"pages":[447],"source":"set-2"},{"id":"set2-hdmybT90","fingerprint":"3f84bbbfb9958238","chapterId":"set-2","subchapterId":"set2-5.06","type":"CS","text":"Conform principiilor de management comportamental, de ce este important ca echipa stomatologică să fie bine organizată?","options":[{"id":"A","text":"Pentru a demonstra superioritatea profesională în fața părinților."},{"id":"B","text":"Pentru a putea trata mai mulți pacienți într-un interval scurt de timp."},{"id":"C","text":"Deoarece întârzierea și nehotărârea pot motiva o reacție de teamă din partea copilului."},{"id":"D","text":"Pentru a permite echipei să își schimbe planul terapeutic mai ușor."},{"id":"E","text":"Pentru a justifica un cost mai ridicat al tratamentului stomatologic."}],"correct":["C"],"pages":[447],"source":"set-2"},{"id":"set2-3zxhETrS","fingerprint":"e850239410f5b5cf","chapterId":"set-2","subchapterId":"set2-5.06","type":"CS","text":"Care este prima etapă esențială în cadrul managementului comportamental în pedodonție?","options":[{"id":"A","text":"Evaluarea tipologiei comportamentale a copilului de către medic."},{"id":"B","text":"Prima vizită la cabinetul stomatologic pentru familiarizare."},{"id":"C","text":"Aplicarea tehnicilor de comunicare precum \"tell-show-do\"."},{"id":"D","text":"Planificarea judicioasă a copiilor pentru a evita supra-aglomerarea."},{"id":"E","text":"Introducerea copilului în sfera preocupărilor de sănătate orală în mediul familial."}],"correct":["E"],"pages":[448],"source":"set-2"},{"id":"set2-ihrZ21QT","fingerprint":"977c49623b9e913e","chapterId":"set-2","subchapterId":"set2-5.06","type":"CM","text":"Ce atitudini și acțiuni sunt contraindicate părinților pentru a asigura o bună cooperare a copilului la cabinetul stomatologic?","options":[{"id":"A","text":"Evocarea în fața copilului a experiențelor neplăcute avute la stomatolog."},{"id":"B","text":"Urmărirea modului și timpului de erupție a dinților copilului."},{"id":"C","text":"Asimilarea de către copil a unor deprinderi sanogenice privind igiena alimentației."},{"id":"D","text":"Informarea cu privire la mijloacele de prevenție a cariei dentare."},{"id":"E","text":"Apelarea la imaginea seringii sau a medicului stomatolog ca simbol al coerciției."}],"correct":["A","E"],"pages":[448],"source":"set-2"},{"id":"set2-zjFxgkkw","fingerprint":"8065a3e4a1fa12f1","chapterId":"set-2","subchapterId":"set2-5.06","type":"CM","text":"Care sunt caracteristicile recomandate pentru amenajarea unui cabinet stomatologic pediatric pentru a nu fi traumatizant?","options":[{"id":"A","text":"Sală de așteptare amenajată cu mobilier accesibil copiilor și spațiu de joacă."},{"id":"B","text":"Absența oricăror elemente decorative pentru a menține un aspect profesional."},{"id":"C","text":"Utilizarea culorilor pastelate, odihnitoare și a armoniilor de culori."},{"id":"D","text":"Predominanța culorii albe pentru a sugera un mediu steril."},{"id":"E","text":"Halate ale medicilor cu un colorit adecvat."}],"correct":["A","C","E"],"pages":[448],"source":"set-2"},{"id":"set2-J1Nq3Zgh","fingerprint":"0407020cdc5684d8","chapterId":"set-2","subchapterId":"set2-5.06","type":"CS","text":"Ce fenomen poate genera supra-aglomerarea în sala de așteptare și cum poate fi evitat?","options":[{"id":"A","text":"Fenomenul de \"modelare\" (modeling); poate fi evitat prin tehnica \"tell-show-do\"."},{"id":"B","text":"O reacție de frică exacerbată; poate fi evitată prin expunerea excesivă de instrumentar."},{"id":"C","text":"Fenomenul de \"angor temporis\"; poate fi evitat prin planificarea judicioasă a copiilor."},{"id":"D","text":"Eșecul total al tratamentului; poate fi evitat prin obținerea consimțământului informat."},{"id":"E","text":"Ranforsare pozitivă; poate fi evitată prin controlul vocii."}],"correct":["C"],"pages":[448],"source":"set-2"},{"id":"set2-37cjMuNZ","fingerprint":"f87c7f27972349d6","chapterId":"set-2","subchapterId":"set2-5.06","type":"CM","text":"Care sunt obiectivele și acțiunile principale desfășurate în cadrul primei ședințe de tratament stomatologic la copil?","options":[{"id":"A","text":"Evaluarea tipologiei comportamentale a copilului."},{"id":"B","text":"Obținerea consimțământului informat din partea părintelui."},{"id":"C","text":"Familiarizarea copilului cu mediul și echipa stomatologică."},{"id":"D","text":"Realizarea periajului profesional și instruirea privind igiena orală."},{"id":"E","text":"Efectuarea unor proceduri dureroase, dar necesare obiectiv."}],"correct":["A","B","C"],"pages":[448],"source":"set-2"},{"id":"set2-8B25UNHS","fingerprint":"62dc5f9dcee18140","chapterId":"set-2","subchapterId":"set2-5.06","type":"CS","text":"Din ce categorie de tehnici de abordare non-farmacologice face parte metoda \"hand over mouth\" (mâna peste gură)?","options":[{"id":"A","text":"Tehnici de modulare comportamentală."},{"id":"B","text":"Tehnici de comunicare verbală."},{"id":"C","text":"Metode de distragere a atenției."},{"id":"D","text":"Tehnici de ranforsare pozitivă."},{"id":"E","text":"Tehnici de comunicare non-verbală."}],"correct":["A"],"pages":[448],"source":"set-2"},{"id":"set2-C_dcPBvF","fingerprint":"a5053ffd182162cc","chapterId":"set-2","subchapterId":"set2-5.06","type":"CM","text":"Ce elemente contribuie la considerarea primului contact dintre copil și medic drept o formă de psihoterapie?","options":[{"id":"A","text":"Un comportament amical față de copil."},{"id":"B","text":"Aplicarea imediată a tehnicii \"hand over mouth\"."},{"id":"C","text":"Expunerea intempestivă a instrumentarului."},{"id":"D","text":"Vorbe prietenoase și un zâmbet înțelegător."},{"id":"E","text":"Obținerea consimțământului informat de la părinte."}],"correct":["A","D"],"pages":[448],"source":"set-2"},{"id":"set2-ywoyEjIN","fingerprint":"6d7a19a37659f17c","chapterId":"set-2","subchapterId":"set2-5.06","type":"CM","text":"Care dintre următoarele metode sunt considerate tehnici de comunicare utilizate în abordarea non-farmacologică a pacientului copil?","options":[{"id":"A","text":"Controlul vocii"},{"id":"B","text":"Ranforsarea pozitivă"},{"id":"C","text":"Tehnica “tell-show-do”"},{"id":"D","text":"Comunicarea verbală"},{"id":"E","text":"Semnalul “stop”"}],"correct":["B","C","D"],"pages":[449],"source":"set-2"},{"id":"set2-tFPb6DXK","fingerprint":"0e4b026acf12f76a","chapterId":"set-2","subchapterId":"set2-5.06","type":"CM","text":"Ce caracteristici sunt recomandate în comunicarea verbală cu pacientul copil pentru a asigura o colaborare eficientă?","options":[{"id":"A","text":"Evitarea comenzilor bruște în orice situație, pentru a nu speria copilul."},{"id":"B","text":"Utilizarea unui limbaj simplu, accesibil și afectuos, dar ferm."},{"id":"C","text":"Menținerea unui timbru al vocii calm, lent și liniștit."},{"id":"D","text":"Utilizarea eufemismelor pentru a descrie instrumentele și procedurile."},{"id":"E","text":"Formularea exclusivă de întrebări care solicită răspunsuri de tip “da/nu” pentru claritate."}],"correct":["B","C","D"],"pages":[449],"source":"set-2"},{"id":"set2-p6YNgfC9","fingerprint":"8ebb9441a450e4dc","chapterId":"set-2","subchapterId":"set2-5.06","type":"CS","text":"Care este distanța de comunicare considerată optimă pentru a permite dialogul cu un pacient copil?","options":[{"id":"A","text":"Peste 120 cm"},{"id":"B","text":"Nu există o distanță specifică recomandată."},{"id":"C","text":"Exact 150 cm"},{"id":"D","text":"Între 50 și 120 cm"},{"id":"E","text":"Sub 50 cm"}],"correct":["D"],"pages":[449],"source":"set-2"},{"id":"set2-hQiHckNK","fingerprint":"358cf02d1f7cda2a","chapterId":"set-2","subchapterId":"set2-5.06","type":"CS","text":"Ce efect are modularea vocii în cadrul comunicării non-verbale cu un pacient copil?","options":[{"id":"A","text":"Ridicarea ușoară a tonului poate capta atenția copilului."},{"id":"B","text":"Scăderea tonului este folosită pentru a impune autoritate."},{"id":"C","text":"Ridicarea tonului are întotdeauna rolul de a calma copilul."},{"id":"D","text":"Un ton constant este esențial pentru a nu deruta copilul."},{"id":"E","text":"Scăderea tonului indică finalizarea procedurii."}],"correct":["A"],"pages":[449],"source":"set-2"},{"id":"set2-lwFZjHSP","fingerprint":"051c032a919ad257","chapterId":"set-2","subchapterId":"set2-5.06","type":"CM","text":"Prin ce modalități senzoriale se realizează prezentarea instrumentelor în cadrul tehnicii “tell-show-do”?","options":[{"id":"A","text":"Tactilă, prin atingerea instrumentului de către copil."},{"id":"B","text":"Demonstrativă, exclusiv pe mâna medicului."},{"id":"C","text":"Auditivă, prin activarea instrumentului în afara cavității orale."},{"id":"D","text":"Gustativă, în cazul pastelor profilactice."},{"id":"E","text":"Vizuală, prin arătarea instrumentului."}],"correct":["A","C","D","E"],"pages":[449],"source":"set-2"},{"id":"set2-PGujKh0F","fingerprint":"6440802c450a0551","chapterId":"set-2","subchapterId":"set2-5.06","type":"CS","text":"Cum trebuie adaptată atitudinea medicului stomatolog în abordarea pacientului copil?","options":[{"id":"A","text":"Trebuie să fie standardizată pentru toți copiii, pentru a asigura obiectivitate."},{"id":"B","text":"Trebuie să fie diferențiată în funcție de etapa de vârstă și tipologia comportamentală."},{"id":"C","text":"Trebuie să prioritizeze comenzile bruște pentru a scurta timpul de lucru."},{"id":"D","text":"Trebuie să se bazeze exclusiv pe specificul afecțiunii medicale."},{"id":"E","text":"Trebuie să inspire în principal nervozitate și panică pentru a impune respect."}],"correct":["B"],"pages":[449],"source":"set-2"},{"id":"set2-lyZOljb4","fingerprint":"262dd6a5fb63d251","chapterId":"set-2","subchapterId":"set2-5.06","type":"CS","text":"Care este principiul de bază al metodei de distragere a atenției în managementul comportamentului la copilul mic?","options":[{"id":"A","text":"Obținerea unui semnal non-verbal de la copil pentru a opri temporar procedura."},{"id":"B","text":"Deturnarea atenției copilului de la un moment potențial dureros către un subiect de interes pentru acesta."},{"id":"C","text":"Utilizarea modulării pozitive a vocii și a expresiei faciale pentru a încuraja copilul."},{"id":"D","text":"Ignorarea unui comportament necorespunzător minor pentru a încuraja autocorectarea."},{"id":"E","text":"Recompensarea copilului pentru un comportament adecvat, pentru a întări cooperarea viitoare."}],"correct":["B"],"pages":[450],"source":"set-2"},{"id":"set2--fePGZkS","fingerprint":"9344e053d8f46b1d","chapterId":"set-2","subchapterId":"set2-5.06","type":"CM","text":"Care dintre următoarele acțiuni reprezintă exemple concrete de aplicare a tehnicii de distragere a atenției?","options":[{"id":"A","text":"Discutarea cu copilul despre personajele sale îndrăgite din desene animate."},{"id":"B","text":"Medicul îi adresează copilului întrebări despre animalul său de companie."},{"id":"C","text":"Oferirea unei recompense la finalul ședinței de tratament."},{"id":"D","text":"Medicul îl felicită pe copil pentru comportamentul său cooperant."},{"id":"E","text":"Audierea unei melodii în timpul unei proceduri medicale."}],"correct":["A","B","E"],"pages":[450],"source":"set-2"},{"id":"set2-22aJgRo9","fingerprint":"517ae1cd37cb2060","chapterId":"set-2","subchapterId":"set2-5.06","type":"CS","text":"Ce presupune tehnica de ranforsare pozitivă în gestionarea comportamentului pediatric?","options":[{"id":"A","text":"Stabilirea unui semnal prin care copilul poate cere oprirea procedurii."},{"id":"B","text":"Ignorarea oricărui tip de comportament necorespunzător, contând pe conștientizarea copilului."},{"id":"C","text":"Punerea unor întrebări despre jucăriile preferate pentru a muta focusul copilului de la procedură."},{"id":"D","text":"Utilizarea laudelor sau a recompenselor pentru a încuraja și a întări un comportament cooperant."},{"id":"E","text":"Aplicarea unei tehnici verbale pentru a deturna atenția în momentul unei jene dureroase."}],"correct":["D"],"pages":[450],"source":"set-2"},{"id":"set2-hYZOgowp","fingerprint":"8ca109d3635a46bb","chapterId":"set-2","subchapterId":"set2-5.06","type":"CM","text":"Care dintre următoarele sunt considerate metode de aplicare a ranforsării pozitive?","options":[{"id":"A","text":"Neglijarea unui comportament necorespunzător de mică importanță."},{"id":"B","text":"Lauda verbală adresată copilului pentru cooperarea sa."},{"id":"C","text":"Demonstrații fizice potrivite de afecțiune."},{"id":"D","text":"Modularea pozitivă a vocii și a expresiei faciale din partea echipei medicale."},{"id":"E","text":"Utilizarea unei cutii muzicale pentru a capta interesul copilului."}],"correct":["A","B","C","D"],"pages":[450],"source":"set-2"},{"id":"set2-_r3tNuDB","fingerprint":"5381ba93ce3855b9","chapterId":"set-2","subchapterId":"set2-5.06","type":"CM","text":"Care sunt afirmațiile adevărate privind prima consultație stomatologică în etapa micii copilării (0-2 ani)?","options":[{"id":"A","text":"Perioada de timp preferabilă pentru control este dimineața, cu ședințe scurte de 1 până la 5 minute."},{"id":"B","text":"Copilul trebuie separat de mamă pentru a facilita examenul clinic."},{"id":"C","text":"Frații copilului pot asista în cabinet pentru a reduce anxietatea pacientului."},{"id":"D","text":"Plânsul copilului la această vârstă este întotdeauna un semn de frică reală sau durere extremă."},{"id":"E","text":"Copilul poate fi așezat cu capul pe genunchii examinatorului și picioarele pe genunchii părintelui."}],"correct":["A","E"],"pages":[443],"source":"set-2"},{"id":"set2-dFT9XLax","fingerprint":"bd95342b50f3acd4","chapterId":"set-2","subchapterId":"set2-5.06","type":"CM","text":"Care dintre următoarele caracteristici și strategii sunt specifice perioadei preșcolare de la 2 la 4 ani, în cadrul cabinetului dentar?","options":[{"id":"A","text":"Copilul este capabil să se focalizeze simultan pe mai multe obiecte."},{"id":"B","text":"Capacitatea de concentrare a atenției variază între 4 și 8 minute."},{"id":"C","text":"Sunt recomandate întrebările cu potențial răspuns negativ pentru a testa cooperarea copilului."},{"id":"D","text":"Copilul este încă foarte dependent de părinți, care trebuie să rămână în sala de așteptare."},{"id":"E","text":"Se recomandă programarea ședințelor la finalul zilei, când copilul este mai relaxat."}],"correct":["B","D"],"pages":[443],"source":"set-2"},{"id":"set2-8Zj5m8Ps","fingerprint":"d0b37ccb03b52a29","chapterId":"set-2","subchapterId":"set2-5.06","type":"CM","text":"Ce abordări sunt recomandate de către medicul pedodont în managementul comportamental al copilului aflat în perioada preșcolară de la 4 la 6 ani?","options":[{"id":"A","text":"Se recomandă introducerea frecventă a pauzelor în timpul lucrului pentru a crește cooperarea."},{"id":"B","text":"Apelul la vanitatea copilului este permis atâta timp cât acesta nu este umilit."},{"id":"C","text":"Medicul poate încuraja participarea activă a copilului prin ținerea oglinzii sau a unui rulou de vată."},{"id":"D","text":"Copilul trebuie mereu acompaniat de părinte în cabinet la fiecare ședință de tratament."},{"id":"E","text":"La această etapă, noțiunea timpului este perfect consolidată, permițând vizite prelungite."}],"correct":["B","C"],"pages":[444],"source":"set-2"},{"id":"set2-9diNEaX2","fingerprint":"07229ea62df9a505","chapterId":"set-2","subchapterId":"set2-5.06","type":"CM","text":"Identificați afirmațiile adevărate privind managementul pacientului în perioada școlară (6-11 ani) și în adolescență (12-15 ani):","options":[{"id":"A","text":"În perioada școlară, dacă pacientul este coleric, medicul trebuie să facă apel la rațiune pentru a obține cooperarea."},{"id":"B","text":"La vârsta de 11 ani, pacientul respinge ideea de a i se acorda încredere, preferând o atitudine pur autoritară din partea medicului."},{"id":"C","text":"În perioada adolescenței (12-15 ani), medicul trebuie să critice direct și să interzică ferm consumul de zahăr pentru o motivare eficientă."},{"id":"D","text":"Motivarea igienei orale în adolescență trebuie abordată la fiecare ședință, în special dacă există un tratament ortodontic asociat."},{"id":"E","text":"La copilul de 6-11 ani, se poate face apel la mândria sau curajul său pentru a depăși refuzul efortului reprezentat de tratament."}],"correct":["D","E"],"pages":[444],"source":"set-2"},{"id":"set2-XvkgipCB","fingerprint":"67a4d56e76a1e89f","chapterId":"set-2","subchapterId":"set2-5.06","type":"CS","text":"Referitor la capacitatea de concentrare și managementul timpului în tratamentul pedodontic, care dintre următoarele corelații este corectă?","options":[{"id":"A","text":"La etapa 4-6 ani, medicul trebuie să acorde pauze regulate, deoarece copilul conștientizează trecerea timpului."},{"id":"B","text":"În mica copilărie (0-2 ani), puterea de concentrare a copilului variază de la 1 la 5 minute, preferându-se ședințe scurte dimineața."},{"id":"C","text":"În perioada preșcolară de la 2 la 4 ani, timpul este măsurat optim prin tăcerea medicului, pentru a favoriza introspecția pacientului."},{"id":"D","text":"Mica copilărie (0-2 ani) presupune o putere de concentrare cuprinsă între 4 și 8 minute."},{"id":"E","text":"În perioada preșcolară de la 2 la 4 ani, copilul are noțiunea timpului bine definită."}],"correct":["B"],"pages":[443],"source":"set-2"},{"id":"set2-xs9WBAR0","fingerprint":"bb931dec994bb91b","chapterId":"set-2","subchapterId":"set2-5.06","type":"CS","text":"Care este o caracteristică evolutivă și descriptivă specifică anxietății dentare?","options":[{"id":"A","text":"Debutează în timpul perioadei preșcolare și prezintă o creștere moderată ulterioară."},{"id":"B","text":"Cunoaște un apogeu la vârste mici, urmat de un declin drastic pe parcursul dezvoltării."},{"id":"C","text":"Se manifestă ca o atitudine defensivă cu stare de agitație motorie imediată la contactul cu un stimul amenințător."},{"id":"D","text":"Reprezintă o emoție naturală bazată pe percepția unei amenințări reale referitoare la un obiect specific."},{"id":"E","text":"Este acompaniată de manifestări dramatice sau isterice provocate de un stimul extern."}],"correct":["A"],"pages":[445],"source":"set-2"},{"id":"set2--ytfE5Xa","fingerprint":"54cc2428605965a2","chapterId":"set-2","subchapterId":"set2-5.06","type":"CM","text":"Care sunt manifestările clinice și caracteristicile asociate fricii dentare?","options":[{"id":"A","text":"Amânarea vizitei la medicul stomatolog"},{"id":"B","text":"Stare de agitație motorie cu manifestări dramatice sau isterice"},{"id":"C","text":"Atitudine defensivă acompaniată de o ușoară neliniște"},{"id":"D","text":"Reacție emoțională normală la stimulii amenințători din situația clinică"},{"id":"E","text":"Percepția unui pericol iminent, vag și nedeterminat, cu un sentiment nespecific de neliniște"}],"correct":["B","C","D"],"pages":[445],"source":"set-2"},{"id":"set2-6MuqEfnA","fingerprint":"442197b93df4a230","chapterId":"set-2","subchapterId":"set2-5.06","type":"CM","text":"Care sunt caracteristicile clinice și comportamentale ale odontofobiei?","options":[{"id":"A","text":"Duce în timp la evitarea tratamentelor stomatologice necesare sau la tolerarea acestora cu spaimă."},{"id":"B","text":"Reprezintă un tip sever de anxietate dentară caracterizat printr-o frică marcată și persistentă."},{"id":"C","text":"Cunoaște un declin drastic al simptomatologiei odată cu depășirea perioadei preșcolare."},{"id":"D","text":"Se referă exclusiv la un pericol iminent, vag și nedeterminat, fără un obiect specific."},{"id":"E","text":"Interferă în mod semnificativ cu rutina zilnică și viața socială a pacientului."}],"correct":["A","B","E"],"pages":[445],"source":"set-2"},{"id":"set2-4NdiINGB","fingerprint":"663f6d7d621965df","chapterId":"set-2","subchapterId":"set2-5.06","type":"CS","text":"Care dintre următoarele afirmații descriu relația dintre problemele de comportament, frica dentară și anxietatea dentară în context clinic?","options":[{"id":"A","text":"Problemele de comportament sunt exclusiv rezultatul direct al fricii și anxietății dentare resimțite de pacient."},{"id":"B","text":"Copiii cu frică și anxietate dentară manifestă invariabil o atitudine zgomotoasă și de opoziție fizică la tratament."},{"id":"C","text":"Copiii pot prezenta probleme de comportament în cabinetul stomatologic fără a asocia frică sau anxietate dentară."},{"id":"D","text":"Problemele de comportament reprezintă ceea ce simte pacientul, în timp ce anxietatea dentară este ceea ce observă medicul."},{"id":"E","text":"Comportamentul cooperant și pasiv exclude prezența anxietății dentare pe parcursul tratamentului."}],"correct":["C"],"pages":[445],"source":"set-2"},{"id":"set2-I8qpm-Bb","fingerprint":"dd0f4ff5a0c74b26","chapterId":"set-2","subchapterId":"set2-5.06","type":"CM","text":"Care dintre următoarele caracteristici definesc tipurile de comportament asociate cu frica dentară și problemele de comportament?","options":[{"id":"A","text":"Impulsivitatea este definită prin prezența nerăbdării și lipsa perseverenței."},{"id":"B","text":"Hiperreactivitatea determină o stare de iritabilitate în care copilul devine agresiv când este frustrat."},{"id":"C","text":"Emoționalitatea negativă se caracterizează prin tendința copilului de a interveni rapid în discuții."},{"id":"D","text":"Timiditatea se manifestă prin tendința copilului de a fi mai încet și de a-și lua un timp de adaptare în situații noi."},{"id":"E","text":"Emoționalitatea negativă presupune iritabilitate, copilul devenind ușor agresiv în situații de frustrare."}],"correct":["A","D","E"],"pages":[445],"source":"set-2"},{"id":"set2-2kS6OL7n","fingerprint":"7f71dae85c736459","chapterId":"set-2","subchapterId":"set2-5.06","type":"CS","text":"Care este considerată cea mai elocventă metodă de evaluare a tiparelor comportamentale ale copilului față de tratamentul stomatologic?","options":[{"id":"A","text":"Chestionarele completate de copil înainte de începerea procedurilor."},{"id":"B","text":"Interviul clinic standardizat pentru determinarea gradului de impulsivitate."},{"id":"C","text":"Chestionarele completate de un părinte pentru identificarea fricii dentare."},{"id":"D","text":"Utilizarea scalelor de evaluare a comportamentului copilului."},{"id":"E","text":"Observarea directă a răspunsului fiziologic prin monitorizarea indicatorilor."}],"correct":["D"],"pages":[446],"source":"set-2"},{"id":"set2-H_4lq9gF","fingerprint":"ecf6194b5f148121","chapterId":"set-2","subchapterId":"set2-5.06","type":"CM","text":"Ce caracteristici prezintă scala de evaluare a comportamentului propusă de Frankl?","options":[{"id":"A","text":"Este o scală de la I la IV utilizată pentru a nota comportamentul la începutul tratamentului stomatologic."},{"id":"B","text":"Poate fi utilizată operativ pentru înregistrarea comportamentului copilului direct în cabinetul stomatologic."},{"id":"C","text":"Evoluția pacientului este notată ulterior prin semnele \"+\" pentru o evoluție favorabilă sau \"-\" pentru o evoluție nefavorabilă."},{"id":"D","text":"Prezintă avantajul de a reda informații suficiente și detaliate despre problemele clinice ale pacientului."},{"id":"E","text":"Se bazează în primul rând pe monitorizarea indicatorilor fiziologici pe parcursul intervenției."}],"correct":["A","B","C"],"pages":[446],"source":"set-2"},{"id":"set2-pp0N1y4C","fingerprint":"f10e65df1201bae2","chapterId":"set-2","subchapterId":"set2-5.06","type":"CS","text":"Ce dezavantaj major este asociat cu utilizarea scalelor de evaluare a comportamentului în cabinetul de medicină dentară pediatrică?","options":[{"id":"A","text":"Comportamentul schimbător al copiilor anxioși în diferite situații din mediul stomatologic."},{"id":"B","text":"Necesitatea completării unor formulare extinse de către aparținători înainte de tratament."},{"id":"C","text":"Faptul că evaluarea se limitează exclusiv la înregistrarea parametrilor fiziologici obiectivi."},{"id":"D","text":"Subiectivismul răspunsurilor oferite în chestionarele completate de copil."},{"id":"E","text":"Incapacitatea acestora de a evalua nivelul de cooperare a copilului în timpul tratamentului."}],"correct":["A"],"pages":[446],"source":"set-2"},{"id":"set2-aiSpLOQw","fingerprint":"ae19f29112ed7f93","chapterId":"set-2","subchapterId":"set2-5.06","type":"CS","text":"Ce trăsături definesc comportamentul de tip II (negativ) în evaluarea gradului de cooperare a pacientului pediatric?","options":[{"id":"A","text":"Copilul are un raport bun cu echipa stomatologică, râde și se bucură de tratament."},{"id":"B","text":"Copilul plânge intens, refuză tratamentul și prezintă o atitudine de negativism extrem."},{"id":"C","text":"Copilul înțelege importanța profilaxiei și urmează instrucțiunile fără rezerve."},{"id":"D","text":"Copilul este îmbufnat, retras, are rezerve și acceptă greu tratamentul stomatologic."},{"id":"E","text":"Copilul are bunăvoința să asculte echipa stomatologică, acceptă tratamentul și respectă ședințele."}],"correct":["D"],"pages":[446,447],"source":"set-2"},{"id":"set2-SdHVa5ln","fingerprint":"bf5e28f78f1705af","chapterId":"set-2","subchapterId":"set2-5.06","type":"CM","text":"Care dintre următoarele atitudini sunt încadrate în comportamentul total negativ (tip I) la pacienții pediatrici?","options":[{"id":"A","text":"Urmarea recomandărilor medicului în prezența unei anumite tensiuni interioare, cu păstrarea unor rezerve."},{"id":"B","text":"Plânsul intens însoțit de un comportament incontrolabil la preșcolarul mare sau copilul de vârstă mijlocie."},{"id":"C","text":"Rezistența pasivă opusă de adolescent, manifestată ca un comportament sfidător asociat anxietății extreme."},{"id":"D","text":"Ușorul negativism manifestat de un copil timid și plângăreț, de vârstă mijlocie."},{"id":"E","text":"Refuzul tratamentului pe fondul unui comportament imatur, determinat de neînțelegerea motivului vizitei la stomatolog."}],"correct":["B","C","E"],"pages":[446,447],"source":"set-2"},{"id":"set2-b9mMQCJv","fingerprint":"3f93a98c293b5213","chapterId":"set-2","subchapterId":"set2-5.06","type":"CM","text":"Care dintre următoarele afirmații descriu comportamentul pozitiv (tip III) la copilul aflat în cabinetul stomatologic?","options":[{"id":"A","text":"Copilul urmează recomandările medicului în cadrul unei colaborări bune, dar există o anumită tensiune și rezerve din partea sa."},{"id":"B","text":"Copilul are un comportament irascibil și plângăreț care deranjează medicul în timpul lucrului, dar tratamentul este continuat."},{"id":"C","text":"Copilul refuză orice manoperă stomatologică din cauza unui comportament imatur și nu înțelege motivul tratamentului."},{"id":"D","text":"Pacientul are un raport bun cu echipa, este interesat de proceduri, se bucură și râde pe scaunul stomatologic."},{"id":"E","text":"Pacientul are bunăvoința să asculte echipa stomatologică, deși nu are o atitudine pozitivă de bunăvoie."}],"correct":["A","B","E"],"pages":[446,447],"source":"set-2"},{"id":"set2-jtig8fRq","fingerprint":"26987501257474ab","chapterId":"set-2","subchapterId":"set2-5.06","type":"CS","text":"Un pacient în vârstă de 5 ani se prezintă în cabinetul stomatologic, fiind vizibil supraprotejat de părinți. Acesta intră în contact cu puțini oameni și colaborează greu cu echipa medicală. Pe parcursul vizitei este îmbufnat, retras și are rezerve evidente, acceptând greu tratamentul fără a manifesta însă un negativism pronunțat. În ce categorie se încadrează acest pacient?","options":[{"id":"A","text":"Tip I (comportament total negativ)"},{"id":"B","text":"Tip V (comportament neutru)"},{"id":"C","text":"Tip IV (comportament total pozitiv)"},{"id":"D","text":"Tip III (comportament pozitiv)"},{"id":"E","text":"Tip II (comportament negativ)"}],"correct":["E"],"pages":[446,447],"source":"set-2"},{"id":"set2-nayoMPU1","fingerprint":"3dcb0698cc682542","chapterId":"set-2","subchapterId":"set2-5.06","type":"CM","text":"Care pacienți manifestă un comportament sfidător, încadrat în tipul I (total negativ) de evaluare a cooperării?","options":[{"id":"A","text":"Adolescentul, prin rezistența pasivă ca formă de comportament extrem de negativ asociat anxietății."},{"id":"B","text":"Copilul mare cu probleme psihice, caracterizat de un comportament incontrolabil."},{"id":"C","text":"Copilul răsfățat de vârstă mijlocie, prin rezistență activă sau pasivă."},{"id":"D","text":"Copilul mic cu comportament imatur, care nu înțelege motivul tratamentului."},{"id":"E","text":"Copilul preșcolar ce prezintă o anxietate extremă și un comportament necontrolabil."}],"correct":["A","C"],"pages":[446,447],"source":"set-2"},{"id":"set2-ElJx-KF6","fingerprint":"705df1afa1c72c95","chapterId":"set-2","subchapterId":"set2-5.06","type":"CS","text":"Care dintre următoarele reprezintă fundamentul managementului comportamental definit prin abilitatea echipei stomatologice de a face față rațional situației cu care se confruntă, gestionând comportamentele nedorite și menținând o stare de calm?","options":[{"id":"A","text":"Toleranța"},{"id":"B","text":"Transparența"},{"id":"C","text":"Abordarea pozitivă"},{"id":"D","text":"Organizarea"},{"id":"E","text":"Flexibilitatea"}],"correct":["A"],"pages":[447],"source":"set-2"},{"id":"set2-AJNL-ViQ","fingerprint":"eb49181ef246ca6e","chapterId":"set-2","subchapterId":"set2-5.06","type":"CM","text":"Care sunt etapele care fac parte din secvențializarea managementului comportamental în pedodonție?","options":[{"id":"A","text":"Modificarea atitudinii pozitive în funcție de nuanțele intermediare de decizie"},{"id":"B","text":"Expunerea timpurie și exhaustivă a instrumentarului ascuțit"},{"id":"C","text":"Evaluarea tipologiei comportamentale a copilului"},{"id":"D","text":"Obținerea consimțământului asupra diagnosticului și tratamentului propus"},{"id":"E","text":"Controlul permanent al durerii și stress-ului"}],"correct":["C","D","E"],"pages":[447],"source":"set-2"},{"id":"set2-WhtvcJrr","fingerprint":"08654f46cad7160e","chapterId":"set-2","subchapterId":"set2-5.06","type":"CM","text":"Care dintre următoarele se încadrează în categoria tehnicilor de modulare comportamentală utilizate în pedodonție?","options":[{"id":"A","text":"Semnalul „stop”"},{"id":"B","text":"Tehnica „hand over mouth” (mâna peste gură)"},{"id":"C","text":"Tehnica „tell-show-do”"},{"id":"D","text":"Metoda distragerii atenției"},{"id":"E","text":"Controlul vocii"}],"correct":["A","B","E"],"pages":[448],"source":"set-2"},{"id":"set2-iCKAb1DL","fingerprint":"cee938ad78d32759","chapterId":"set-2","subchapterId":"set2-5.06","type":"CS","text":"Care este recomandarea principală privind amenajarea mediului ambiental și organizarea programărilor la cabinetul de stomatologie pediatrică?","options":[{"id":"A","text":"Utilizarea instrumentarului complex încă de la prima vizită pentru a testa toleranța pacientului"},{"id":"B","text":"Planificarea exclusivă a copiilor necooperanți în aceeași jumătate a zilei"},{"id":"C","text":"Programarea pacienților cu nivel crescut de anxietate în mod izolat, fără alți copii în cabinet"},{"id":"D","text":"Utilizarea predominantă a culorii albe pentru a sugera o igienă riguroasă"},{"id":"E","text":"Evitarea supra-aglomerării pentru a preveni fenomenul de „angor temporis”"}],"correct":["E"],"pages":[448],"source":"set-2"},{"id":"set2-_mt_9CtO","fingerprint":"2433382e5b720237","chapterId":"set-2","subchapterId":"set2-5.06","type":"CS","text":"În cadrul fundamentelor managementului comportamental, ce presupune principiul transparenței în relația cu pacientul copil?","options":[{"id":"A","text":"Flexibilitatea de a modifica planul terapeutic în orice moment, fără informarea prealabilă a copilului"},{"id":"B","text":"Prezentarea exhaustivă a tuturor opțiunilor terapeutice, inclusiv cele dureroase, sub formă de nuanțe intermediare"},{"id":"C","text":"Permisiunea oferită părinților de a asista la întregul act terapeutic pentru a asigura vizibilitatea completă a procedurilor"},{"id":"D","text":"Oferirea unor variante precise de tip „alb sau negru”, fără nuanțe intermediare"},{"id":"E","text":"Utilizarea metodelor de comunicare non-verbală în defavoarea celor verbale pentru a spori încrederea"}],"correct":["D"],"pages":[447],"source":"set-2"},{"id":"set2--IBhCv4K","fingerprint":"d413b9bc3044e612","chapterId":"set-2","subchapterId":"set2-5.06","type":"CM","text":"Care sunt acțiunile recomandate a fi efectuate în timpul primei ședințe stomatologice la pacientul copil?","options":[{"id":"A","text":"Expunerea intempestivă a instrumentarului pentru testarea toleranței la stres"},{"id":"B","text":"Realizarea anchetei funcționale și evaluarea tipologiei comportamentale a copilului"},{"id":"C","text":"Obținerea consimțământului informat din partea părintelui"},{"id":"D","text":"Realizarea unor proceduri premature ca etapă de accept pentru a scurta numărul de ședințe"},{"id":"E","text":"Familiarizarea copilului cu mediul din cabinet și cu echipa stomatologică"}],"correct":["B","C","E"],"pages":[448],"source":"set-2"},{"id":"set2-keS24sDC","fingerprint":"126fdf164bfff2e0","chapterId":"set-2","subchapterId":"set2-5.06","type":"CM","text":"Care sunt caracteristicile comunicării verbale cu pacientul copil pe durata tratamentului stomatologic?","options":[{"id":"A","text":"Utilizarea de eufemisme pentru descrierea procedurilor, materialelor și instrumentelor."},{"id":"B","text":"Excluderea completă a comenzilor bruște, pentru a nu perturba confortul psihic al pacientului."},{"id":"C","text":"Utilizarea numelui mic al copilului într-un limbaj simplu, accesibil, afectuos, dar ferm."},{"id":"D","text":"Trecerea de la imperativul „tu” la „eu”."},{"id":"E","text":"Formularea de întrebări și comentarii care să solicite exclusiv răspunsuri de tip „da” sau „nu”."}],"correct":["A","C","D"],"pages":[449,450],"source":"set-2"},{"id":"set2-lG4FZFRD","fingerprint":"237e6df10aeaf770","chapterId":"set-2","subchapterId":"set2-5.06","type":"CM","text":"Care sunt afirmațiile corecte referitoare la modalitățile de comunicare non-verbală și efectele lor asupra pacientului copil?","options":[{"id":"A","text":"Poziția corpului și a capului medicului, ușor înclinate spre înainte, constituie un semn al înțelegerii."},{"id":"B","text":"Scăderea tonului vocii reprezintă metoda principală de captare a atenției pacientului necooperant."},{"id":"C","text":"Atingerea este un gest care trebuie evitat, deoarece reduce eficiența transmiterii mesajelor verbale."},{"id":"D","text":"Distanța de comunicare pentru a permite dialogul se situează între 50 și 120 cm."},{"id":"E","text":"Privirea directă denotă acordarea nemijlocită a atenției."}],"correct":["A","D","E"],"pages":[449,450],"source":"set-2"},{"id":"set2-YpxuQDSs","fingerprint":"ffa5b95ae17b23e7","chapterId":"set-2","subchapterId":"set2-5.06","type":"CM","text":"Ce elemente sunt incluse în tehnica „tell-show-do” aplicată în pedodonție?","options":[{"id":"A","text":"Componenta olfactivă și gustativă este vizată cu precădere în utilizarea anesteziei locale sau a pastelor profilactice."},{"id":"B","text":"Explicarea auditivă presupune activarea instrumentului exclusiv în interiorul cavității orale, pentru a simula exact tratamentul."},{"id":"C","text":"Demonstrația acționării instrumentelor are loc strict pe mâna medicului, pentru a garanta siguranța copilului."},{"id":"D","text":"Explicarea vizuală se realizează prin arătarea directă a instrumentului ce urmează a fi utilizat."},{"id":"E","text":"Explicarea tactilă implică atingerea instrumentului de către pacientul copil."}],"correct":["A","D","E"],"pages":[449,450],"source":"set-2"},{"id":"set2-NEw3BSbt","fingerprint":"462e40fe2b05a90e","chapterId":"set-2","subchapterId":"set2-5.06","type":"CS","text":"Care este principiul de bază al metodei distragerii atenției utilizate în stomatologia pediatrică?","options":[{"id":"A","text":"Necesită concentrarea exclusivă asupra comportamentelor necorespunzătoare majore pentru a le sancționa verbal."},{"id":"B","text":"Presupune oferirea unei recompense sub formă de laude sau demonstrații fizice de afecțiune pentru finalizarea cu succes a procedurii."},{"id":"C","text":"Se bazează pe familiarizarea copilului cu sunetul și aspectul instrumentarului, activat în prealabil în proximitatea acestuia."},{"id":"D","text":"Constă în deturnarea atenției pacientului spre un subiect agreabil atunci când acesta ar putea resimți o jenă dureroasă."},{"id":"E","text":"Este o tehnică strict non-verbală prin care se modulează tonul vocii pentru a induce relaxarea profundă."}],"correct":["D"],"pages":[449,450],"source":"set-2"},{"id":"set2-iY4yFh5t","fingerprint":"4513fd7a3b776196","chapterId":"set-2","subchapterId":"set2-5.06","type":"CM","text":"Care dintre următoarele atitudini și proceduri corespund corect tehnicilor de gestionare a comportamentului copilului în cabinetul de medicină dentară?","options":[{"id":"A","text":"Ranforsarea pozitivă implică răsplătirea comportamentului prin modularea pozitivă a vocii, lauda și demonstrații fizice de afecțiune."},{"id":"B","text":"Mesajele transmise prin comunicarea non-verbală confirmă competența medicului și asigură pacientul că nu i se va face rău."},{"id":"C","text":"Utilizarea unor termeni precum „albinuță” pentru turbină constituie un mesaj verbal direct, fără valențe eufemistice."},{"id":"D","text":"Ascultarea activă în comunicarea non-verbală presupune retragerea fizică a medicului la o distanță mai mare de 120 cm."},{"id":"E","text":"Ranforsarea pozitivă permite neglijarea unui eventual comportament necorespunzător minor din partea copilului."}],"correct":["A","B","E"],"pages":[449,450],"source":"set-2"}];
